prologue:
/* The game answers with the same id for the same name, but asking costs a lookup, so the
   last few are kept. A sound of no name is nothing to play */
static MOD_UNUSED AmodSoundId sound_id(const char* name) {
    enum { kRemember = 8 };
    static char names[kRemember][64];
    static AmodSoundId ids[kRemember];
    static int filled;
    AmodSoundId id;
    int at;

    if (API->sound == 0 || name == 0 || name[0] == 0) return AMOD_INVALID_SOUND;
    for (at = 0; at < filled; ++at)
        if (strcmp(names[at], name) == 0) return ids[at];

    id = API->sound->Load(SELF, name);
    if (id != AMOD_INVALID_SOUND && filled < kRemember && strlen(name) < sizeof names[0]) {
        strcpy(names[filled], name);
        ids[filled] = id;
        ++filled;
    }
    return id;
}

/* A sound placed in the world keeps playing under a voice. The sheet gives it a name instead,
   so "move the waterfall" and "stop the waterfall" read as themselves */
enum { kSoundVoices = 8 };
static char g_sound_named[kSoundVoices][32];
static AmodVoice g_sound_voice[kSoundVoices];

static MOD_UNUSED int sound_slot(const char* name, int make) {
    int at, free_slot = -1;
    for (at = 0; at < kSoundVoices; ++at) {
        if (g_sound_named[at][0] == 0) {
            if (free_slot < 0) free_slot = at;
            continue;
        }
        if (strcmp(g_sound_named[at], name) == 0) return at;
    }
    if (make == 0 || free_slot < 0 || strlen(name) >= sizeof g_sound_named[0]) return -1;
    strcpy(g_sound_named[free_slot], name);
    g_sound_voice[free_slot] = AMOD_INVALID_VOICE;
    return free_slot;
}

/* pitch of zero or less is refused by the API and would hang the voice, so it is pulled up */
static MOD_UNUSED void sound_play_at(const char* name, const char* file, float x, float y, float z,
                                     int loop, float pitch) {
    const float position[3] = { x, y, z };
    const AmodSoundId id = sound_id(file);
    const int slot = sound_slot(name, 1);
    if (API->sound == 0 || id == AMOD_INVALID_SOUND) return;
    if (pitch <= 0.0f) pitch = 1.0f;

    if (slot >= 0 && g_sound_voice[slot] != AMOD_INVALID_VOICE)
        API->sound->Stop(SELF, g_sound_voice[slot]);   /* one voice per name, so it never piles up */

    {
        const AmodVoice voice = API->sound->PlayAt(SELF, id, position, loop, pitch);
        if (slot >= 0) g_sound_voice[slot] = voice;
    }
}

static MOD_UNUSED void sound_move(const char* name, float x, float y, float z) {
    const float position[3] = { x, y, z };
    const int slot = sound_slot(name, 0);
    if (API->sound == 0 || slot < 0 || g_sound_voice[slot] == AMOD_INVALID_VOICE) return;
    API->sound->Move(SELF, g_sound_voice[slot], position);
}

static MOD_UNUSED void sound_stop(const char* name) {
    const int slot = sound_slot(name, 0);
    if (API->sound == 0 || slot < 0) return;
    if (g_sound_voice[slot] != AMOD_INVALID_VOICE) API->sound->Stop(SELF, g_sound_voice[slot]);
    g_sound_voice[slot] = AMOD_INVALID_VOICE;
    g_sound_named[slot][0] = 0;
}

static MOD_UNUSED int sound_started(const char* name) {
    const int slot = sound_slot(name, 0);
    return slot >= 0 && g_sound_voice[slot] != AMOD_INVALID_VOICE;
}

/* Room loops start when the room is entered and stop when it is left. A room of -1 is the
   one the player is in */
static MOD_UNUSED int sound_room_count(int room) {
    return API->sound != 0 ? API->sound->GetRoomSoundCount(SELF, room) : 0;
}

static MOD_UNUSED int sound_room_read(int room, int index, AmodRoomSound* out) {
    if (API->sound == 0) return 0;
    memset(out, 0, sizeof *out);
    out->structSize = sizeof *out;
    return API->sound->GetRoomSound(SELF, room, index, out);
}

static MOD_UNUSED float sound_room_where(int room, int index, int axis) {
    AmodRoomSound loop;
    if (sound_room_read(room, index, &loop) == 0 || axis < 0 || axis > 2) return 0.0f;
    return loop.position[axis];
}

static MOD_UNUSED int sound_room_id(int room, int index) {
    AmodRoomSound loop;
    if (sound_room_read(room, index, &loop) == 0) return 0;
    return (int)loop.sound;
}

static MOD_UNUSED void sound_room_fill(AmodRoomSound* loop, const char* file,
                                       float x, float y, float z) {
    memset(loop, 0, sizeof *loop);
    loop->structSize = sizeof *loop;
    loop->sound = sound_id(file);
    loop->position[0] = x;
    loop->position[1] = y;
    loop->position[2] = z;
}

/* Takes effect the next time the room is entered, which is what the game does with its own */
static MOD_UNUSED void sound_room_add(int room, const char* file, float x, float y, float z) {
    AmodRoomSound loop;
    sound_room_fill(&loop, file, x, y, z);
    if (API->sound != 0 && loop.sound != AMOD_INVALID_SOUND) API->sound->AddRoomSound(SELF, room, &loop);
}

static MOD_UNUSED void sound_room_set(int room, int index, const char* file,
                                      float x, float y, float z) {
    AmodRoomSound loop;
    sound_room_fill(&loop, file, x, y, z);
    if (API->sound != 0 && loop.sound != AMOD_INVALID_SOUND)
        API->sound->SetRoomSound(SELF, room, index, &loop);
}

static MOD_UNUSED const char* sound_music(void) {
    const char* playing = API->sound != 0 ? API->sound->CurrentMusic(SELF) : 0;
    return playing != 0 ? playing : "";
}

static MOD_UNUSED int sound_music_is(const char* path) {
    return strcmp(sound_music(), path) == 0;
}
